base.retry.go:
package client

// MaxAttempts is the total number of attempts, including the first.
var MaxAttempts = 3

base.client.go:
package client

func Do(send func() error) error {
	var err error
	for i := 0; i < MaxAttempts; i++ {
		if err = send(); err == nil {
			return nil
		}
	}
	return err
}

